INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(18301, 'Jeremiah 19:7', 'Jeremiah', 19, 7, '&nbsp;په دې ځائ کښې به زۀ د يهوداه او د يروشلم د خلقو ټولې منصوبې تباه کړم. زۀ به هغوئ د هغه دشمن په لاس ووژنم، څوک چې د دوئ وينو ته تږى ناست دى، او زۀ به د دوئ لاشونه د هوا د مارغانو او د ځنګلى ځناورو خوراک کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18302, 'Jeremiah 19:8', 'Jeremiah', 19, 8, '&nbsp;زۀ به يروشلم تباه کړم، او د خلقو د خندا به يې کړم. څوک هم چې په دې لار تېريږى نو د هغوئ په تباهۍ به حق حېران شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18303, 'Jeremiah 19:9', 'Jeremiah', 19, 9, '&nbsp;زۀ به د هغوئ دشمنان څوک چې د هغوئ د وينو تږى دى راپاڅوم چې د دوئ ښار نه ګېره واچوى او دوئ ته غټ تکليف ورسوى. او دا ګېره به دومره سخته وى چې دوئ به د خپلو ماشومانو او ګاونډيانو په خوړلو شروع وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18304, 'Jeremiah 19:10', 'Jeremiah', 19, 10, '&nbsp;بيا مالِک خُدائ ما ته وفرمائيل چې هغه کسان چې تا خپل ځان سره بوتلى دى د هغوئ په وړاندې دا منګے چې تا سره دے مات کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18305, 'Jeremiah 19:11', 'Jeremiah', 19, 11, '&nbsp;او هغوئ ته ووايه چې مالِک خُدائ ربُ الافواج فرمائيلى دى، زۀ به د دې منګى په شان دا قوم او دا ښار ټوټې ټوټې کړم چې د بيا جوړېدو امکان به يې نۀ وى. په هغه وخت کښې به هغوئ خپل مړى په توفت کښې ښخوى، تر هغې پورې چې د ښخولو نور ځائ پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18306, 'Jeremiah 19:12', 'Jeremiah', 19, 12, '&nbsp;مالِک خُدائ فرمائى چې، زۀ به دې ښار او د دې د اوسېدونکو سره هم دغه رنګ وکړم. او د دوئ سره به د توفت په شان پليت سلوک وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18307, 'Jeremiah 19:13', 'Jeremiah', 19, 13, '&nbsp;زۀ به د يروشلم ټول کورونه، د يهوداه د بادشاهانو شاهى محلونه لکه د توفت په شان پليت وګرځوم، چا چې د خپلو کورونو په چتونو ستورو ته قربانۍ پېش کړې دى، او د څښلو نذرانې يې نورو بُتانو ته پېش کړې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18308, 'Jeremiah 19:14', 'Jeremiah', 19, 14, '&nbsp;نو بيا يرمياه د توفت نه راواپس شو، کوم ځائ ته چې مالِک خُدائ هغه د پېغام ورکولو دپاره لېږلے وو. نو بيا هغه د مالِک خُدائ د کور په دربار کښې ودرېدو او ټولو خلقو ته يې وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18309, 'Jeremiah 19:15', 'Jeremiah', 19, 15, '&nbsp;”مالِک خُدائ ربُ الافواج، د بنى اِسرائيلو خُدائ پاک فرمائى چې زۀ به په دې ښار او د دې نه ګېرچاپېره ښارونو هغه ټول افتونه راولم چې د کومو ما وړاندې ذکر کړے دے، ځکه چې تاسو په سرکشۍ سره زما خبرو اورېدلو ته تيار نۀ يئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18310, 'Jeremiah 20:1', 'Jeremiah', 20, 1, '&nbsp;کله چې فشحور د اِمير زوئ څوک چې د مالِک خُدائ په کور کښې مشر اِمام وو، هغه څۀ واورېدل د څۀ چې يرمياه پېشګوئې کوله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18311, 'Jeremiah 20:2', 'Jeremiah', 20, 2, '&nbsp;نو هغۀ يرمياه نبى راګېر کړلو او په کوړو يې ووهلو او بيا يې هغه پاس د مالِک خُدائ په کور کښې د بنيامين په دروازه کښې د لرګى په کُنده کښې بند کړلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18312, 'Jeremiah 20:3', 'Jeremiah', 20, 3, '&nbsp;په بله ورځ کله چې فشحور هغه د کُندې نه آزاد کړو، يرمياه هغۀ ته وفرمائيل چې، ”مالِک خُدائ ستا نوے نوم اېښے دے او د نن نه پس به ستا نوم فشحور نۀ وى بلکې په هر اړخ باندې دهشت.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18313, 'Jeremiah 20:4', 'Jeremiah', 20, 4, '&nbsp;ځکه مالِک خُدائ په خپله دا فرمائى چې، زۀ به په تا او ستا په دوستانو باندې دهشت راولم، او تۀ به په خپلو سترګو سره د هغوئ وژل د دشمنانو د لاسه ووينې. زۀ به د يهوداه ټول خلق د بابل بادشاه ته حواله کړم، څوک چې به د هغوئ نه ځينې بابل ته قېديان بوځى او ځينې به په تُوره قتل کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18314, 'Jeremiah 20:5', 'Jeremiah', 20, 5, '&nbsp;زۀ به د دې ښار ټول مال دولت او د هغوئ ټول قيمتى سامانونه او د يهوداه بادشاه خزانې د هغوئ دشمنانو ته حواله کړم. هغوئ به دا لوټ کړى او بابل ته به يې يوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18315, 'Jeremiah 20:6', 'Jeremiah', 20, 6, '&nbsp;ترڅو چې ستا خبره ده فشحوره، تۀ او ستا مکمل خاندان به هم ونيولے شى او بابل ته به بوتلے شى. هلته به تاسو او ستا هغه ټول دوستان مړۀ او ښخ شى چا ته به چې تا په دروغو پېشګوئې کوله چې هيڅ پرواه مۀ کوئ خير به شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18316, 'Jeremiah 20:7', 'Jeremiah', 20, 7, '&nbsp;اے مالِکه خُدايه، تا زۀ دوکه کړم، او زۀ دوکه شوم. تاسو زورَور يئ او زۀ دې مغلوب کړم. زۀ اوس ټوله ورځ د مسخرو شوم، او هر څوک ما پورې ټوقې او خندا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18317, 'Jeremiah 20:8', 'Jeremiah', 20, 8, '&nbsp;کله چې هم زۀ خپله خولۀ خلاصوم، نو بيا ضرور زۀ د ظلم او تباهۍ په حقله چغې سورې وهم. ځکه چې زۀ د مالِک خُدائ د کلام په وجه ټوله ورځ کنځل او بدې ردې تېروم او سپکولے شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18318, 'Jeremiah 20:9', 'Jeremiah', 20, 9, '&nbsp;خو چې کله زۀ ووايم چې، ”زۀ به د مالِک خُدائ په حقله خبرې نۀ کوم او نۀ به نور د هغۀ پېغام چا ته رسوم،“ نو بيا د هغۀ کلام زما په زړۀ کښې لکه د اور په شان بليږى او هغه اور زما هډوکو ته رسيږى. زۀ په ځان کښې د هغۀ د ايسارولو د کوشش په وجه ډېر ستړے شوے يم او زۀ هغه نۀ شم ايسارولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18319, 'Jeremiah 20:10', 'Jeremiah', 20, 10, '&nbsp;ما د خپل ځان په حقله د ډېرو خلقو ګونګوسى اورېدلى دى. هغوئ وائى چې، ”هرې خوا ته دهشت دے بس دهشت. راځئ چې د هغۀ اِطلاع ورکړُو. راځئ چې د هغۀ په حقله اِطلاع ورکړُو.“ زما نزدې دوستان هم زما د غورزېدلو په انتظار دى، او هغوئ وائى چې، ”شايد چې هغه دوکه شى، نو بيا به يې راګېر کړُو او د هغۀ نه به خپله بدله واخلو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18320, 'Jeremiah 20:11', 'Jeremiah', 20, 11, '&nbsp;بلکې مالِک خُدائ د يو طاقتور جنګيالى په شان ما سره دے، نو بيا څوک هم چې زما د ژوند ختمولو پسې دى هغوئ به هيڅکله هم کامياب نۀ شى، او په خپله به تيندکونه وخورى. هغوئ به ناکاميابه شى او په شرمونو به وشرميږى، د هغوئ دا بې‌عزتى به هيڅکله د هېرېدلو نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18321, 'Jeremiah 20:12', 'Jeremiah', 20, 12, '&nbsp;خو اے مالِکه خُدايه، ربُ الافواجه، تاسو په خپله صادق سړے وينئ، او تاسو په خپله د انسان د زړۀ او دماغ ژور سوچونه او رازونه آزمايئ. ما خپل خواست تا ته پېش کړے دے نو په دې وجه تاسو زما بدله اخستل ما ته وښايئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18322, 'Jeremiah 20:13', 'Jeremiah', 20, 13, '&nbsp;د مالِک خُدائ حمد ووايئ. د مالِک خُدائ ثناء صِفت ادا کړئ. هغه غريبانان د شريرانو د لاس نه بچ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18323, 'Jeremiah 20:14', 'Jeremiah', 20, 14, '&nbsp;په هغه ورځ دې لعنت وى په کومه چې زۀ پېدا شوے وم. او هغه ورځ دې مبارکه نۀ وى په کومه ورځ چې زۀ د مور نه پېدا شوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18324, 'Jeremiah 20:15', 'Jeremiah', 20, 15, '&nbsp;په هغه کس دې لعنت وى چا چې زما د پلار د خوشحالولو دپاره دا زېرے راوړے وو چې، ”ستا زوئ پېدا شوے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18325, 'Jeremiah 20:16', 'Jeremiah', 20, 16, '&nbsp;هغه سړے دې د هغه ښارونو په شان شى کوم چې مالِک خُدائ په بې‌رحمۍ سره تباه کړى وُو. هغه دې په سحر کښې د يرې چغې واورى او په غرمه کښې دې د جنګ شور واورى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18326, 'Jeremiah 20:17', 'Jeremiah', 20, 17, '&nbsp;ځکه چې زۀ هغۀ د پېدا کېدو نه وړاندې د مور په ګېډه کښې مړ نۀ کړم، ترڅو چې د هغې ګېډه زما قبر جوړ شوے وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18327, 'Jeremiah 20:18', 'Jeremiah', 20, 18, '&nbsp;زۀ د مور د خېټې نه ولې دُنيا ته راغلم؟ د دې دپاره پېدا شوم چې په دُنيا کښې تکليفونه او کړاونه وګورم، او چې زما ژوند په بې‌عزتۍ کښې ختم شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18328, 'Jeremiah 21:1', 'Jeremiah', 21, 1, '&nbsp;هغه پېغام چې د مالِک خُدائ له خوا نه يرمياه ته ورکړے شو کله چې د يهوداه بادشاه صدقياه د مُلکياه زوئ فشحور او د معسياه زوئ صفنياه اِمام يرمياه ته د دې عرض سره ورولېږل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18329, 'Jeremiah 21:2', 'Jeremiah', 21, 2, '&nbsp;”زمونږ دپاره د مالِک خُدائ نه تپوس وکړه ځکه چې د بابل بادشاه نبوکدنضر او د هغۀ لښکر په مونږ حمله کوى، نو کېدے شى چې مالِک خُدائ زمونږ دپاره د وړاندې په شان معجزه وکړى او نبوکدنضر د دې ځائ نه په وتو مجبور کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18330, 'Jeremiah 21:3', 'Jeremiah', 21, 3, '&nbsp;بيا يرمياه جواب ورکړو، ”تاسو صدقياه بادشاه ته واپس لاړ شئ او ورته ووايئ چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18331, 'Jeremiah 21:4', 'Jeremiah', 21, 4, '&nbsp;مالِک خُدائ، د بنى اِسرائيلو خُدائ پاک دا فرمائى چې، زۀ به ستاسو د جنګ وسله کومه چې ستاسو په لاس کښې ده بې‌کاره کړم او ستاسو خلاف به يې استعمال کړم، کومه چې تاسو د جنګ دپاره د بابل د بادشاه او د بابل د خلقو خلاف به استعمالوئ څوک چې د دېوال نه اخوا دى او په تاسو حمله کوى. نو په حقيقت کښې به زۀ ستاسو دشمنان د دې ښار زړۀ ته راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18332, 'Jeremiah 21:5', 'Jeremiah', 21, 5, '&nbsp;زۀ به په خپله خپل زورَور لاس دراوږد کړم او ستاسو خِلاف به په غصې، قهر، او لوئ غضب سره جنګ وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18333, 'Jeremiah 21:6', 'Jeremiah', 21, 6, '&nbsp;زۀ به په دې ښار سخته وبا رانازله کړم، زۀ به انسانان او ځناور دواړه مړۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18334, 'Jeremiah 21:7', 'Jeremiah', 21, 7, '&nbsp;مالِک خُدائ فرمائى چې د دې نه وروستو به زۀ صدقياه بادشاه او د هغۀ ټول آفسران او د هغۀ نور خلق کوم چې دې ښار کښې اوسيږى او د وبا، جنګ، او قحط نه ژوندى پاتې شوى وى زۀ به هغوئ نبوکدنضر بادشاه ته او د هغوئ دشمن ته حواله کړم څوک چې د هغوئ ژوند ختمولو پسې ګرځى. هغه به هغوئ په تُوره په بې‌دردۍ سره مړۀ کړى، او په دوئ باندې به هيڅ قسمه رحم، مينه او نۀ به پرې څۀ زړۀ سواندے ښکاره کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18335, 'Jeremiah 21:8', 'Jeremiah', 21, 8, '&nbsp;بيا مالِک خُدائ ما ته وفرمائيل چې دې خلقو ته ووايه چې، ”زۀ، مالِک خُدائ ستاسو په وړاندې دوه لارې پېش کوم چې يوه د ژوند او بله د مرګ لاره ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18336, 'Jeremiah 21:9', 'Jeremiah', 21, 9, '&nbsp;هر څوک هم چې په دې ښار کښې پاتې شى نو هغه به په جنګ، قحط او يا د وبا په وجه مړۀ شى. خو هر څوک چې بهر ووځى او خپل ځان بابليانو ته حواله کړى چا چې ښار محاصره کړے دے هغوئ به ژوندى پاتې شى، او هغوئ ته به د ژوندون غنيمت ورکړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18337, 'Jeremiah 21:10', 'Jeremiah', 21, 10, '&nbsp;مالِک خُدائ فرمائى چې، ما دا فېصله کړې ده چې زۀ به دا ښار بچ نۀ کړم او افتونه به پرې نازل کړم، نه چې آبادى. دا به د بابل بادشاه ته حواله کړم او هغه به دا ښار په اور تباه کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18338, 'Jeremiah 21:11', 'Jeremiah', 21, 11, '&nbsp;‏ ”د يهوداه شاهى خاندان ته ووايه، د مالِک خُدائ پېغام واورئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18339, 'Jeremiah 21:12', 'Jeremiah', 21, 12, '&nbsp;اے د داؤد خاندانه، مالِک خُدائ تاسو ته داسې فرمائى، هر سحر د خلقو اِنصاف کوئ د چا نه چې غلا شوې وى او هغوئ ته د ظالمانو د لاس نه خلاصون ورکوئ، ګنې زما غضب به رانازل شى او هر څۀ به لکه د اور په شان وسوزوى او دا به ستاسو د هغه شرارت په وجه داسې بليږى چې هيڅ څوک به يې نۀ شى مړ کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18340, 'Jeremiah 21:13', 'Jeremiah', 21, 13, '&nbsp;مالِک خُدائ فرمائى، اے يروشلمه، زۀ به په ذاتى توګه ستاسو خلاف جنګ کوم، تاسو څوک چې په دې وادۍ بره اوسېږئ او په اوچت ګټ پراتۀ يئ، تاسو څوک چې په ډېر فخر سره وايئ، دلته څوک زمونږ خلاف راتلے شى څۀ؟ او زمونږ پناه ګاه ته څوک راننوتلے شى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18341, 'Jeremiah 21:14', 'Jeremiah', 21, 14, '&nbsp;مالِک خُدائ فرمائى چې، زۀ به ستاسو د عمل په مطابق چې د څومره سزا قابل يئ هومره درکړم. زۀ به ستا د قلعه ګانو د لرګو په ستنو اور بل کړم او د هغې نه ګېرچاپېره چې هر څۀ وى هغه به وسوزوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18342, 'Jeremiah 22:1', 'Jeremiah', 22, 1, '&nbsp;مالِک خُدائ ما ته وفرمائيل چې، ”تۀ د يهوداه د بادشاه محل ته ښکته لاړ شه او هلته دا پېغام بيان کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18343, 'Jeremiah 22:2', 'Jeremiah', 22, 2, '&nbsp;اے د يهوداه بادشاه، د مالِک خُدائ پېغام واوره، تاسو څوک چې د داؤد په تخت ناست يئ، تۀ، او ستا آفسران او ستا قوم څوک چې په دې دروازه تګ راتګ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18344, 'Jeremiah 22:3', 'Jeremiah', 22, 3, '&nbsp;مالِک خُدائ داسې فرمائى چې، اِنصاف او صداقت قائم کړئ. څوک چې لوټ شوے وى هغه د ظالم د لاس نه آزاد کړئ. په مسافرو، يتيمانو او کونډو ظلم او زياتے مۀ کوئ او بې‌ګناه وينه په دې ځائ کښې مۀ توئيوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18345, 'Jeremiah 22:4', 'Jeremiah', 22, 4, '&nbsp;کۀ چرې تاسو په احتياط سره زما په حکمونو عمل وکړئ، نو بيا هغه بادشاه څوک چې په يروشلم کښې د داؤد د اولاد نه د داؤد په تخت ناست دے د هغۀ بادشاهى او د هغۀ اولاد به قائم وى او هغه به د خپلو آفسرانو او د هغه خلقو سره چې په ګاډو او آسونو باندې سوارۀ دى د دې محل په دروازو راداخل شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18346, 'Jeremiah 22:5', 'Jeremiah', 22, 5, '&nbsp;مالِک خُدائ فرمائى چې، کۀ چرې تاسو په دې حکمونو عمل ونۀ کړئ، قسم دې زما په خپل ذات وى چې دا محل به د خاورو ډېرے کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18347, 'Jeremiah 22:6', 'Jeremiah', 22, 6, '&nbsp;نو بيا مالِک خُدائ د يهوداه د بادشاه د محل په حقله داسې فرمائى، کۀ څۀ هم چې د يهوداه محل زما دپاره د جِلعاد په شان مېوه لرونکے او د لبنان د غرونو په شان شين او ښکلے دے، خو زۀ به په يقين سره دا په دشته بدل کړم لکه د هغه ښارونو په شان چې څوک په کښې نۀ اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18348, 'Jeremiah 22:7', 'Jeremiah', 22, 7, '&nbsp;زۀ به ستا د بربادۍ دپاره وسله بند جنګى لښکر درولېږم او هغوئ به ستا ستنې چې د دِيار د ښائسته ونو نه تيارې شوې دى راوباسى او په اور کښې به يې وغورزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18349, 'Jeremiah 22:8', 'Jeremiah', 22, 8, '&nbsp;نو کله چې د ډېرو قومونو خلق په دې ښار باندې تېريږى نو بيا به د يو بل نه دا تپوس کوى چې، مالِک خُدائ ولې د دې لوئ ښار سره داسې سلوک وکړو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18350, 'Jeremiah 22:9', 'Jeremiah', 22, 9, '&nbsp;نو هغوئ ته به جواب ورکړے شى چې، د دې ښار سره داسې سلوک ځکه وشو چې هغوئ د خپل خُدائ پاک سره لوظ مات کړو او د نورو معبودانو عبادت او خِدمت يې وکړو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18351, 'Jeremiah 22:10', 'Jeremiah', 22, 10, '&nbsp;اے د يهوداه خلقو، د مړ شوى بادشاه يوسياه په حقله ژړا مۀ کوئ، او د هغۀ په مرګ ماتم مۀ کوئ. خو د دې په ځائ ډېره سخته ژړا د هغۀ د زوئ سلوم بادشاه په حقله وکړئ، څوک چې د مُلک نه شړلے شوے دے ځکه چې هغه به بيا کله هم واپس رانۀ شى، او نۀ به خپل ذاتى مُلک دوباره وګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18352, 'Jeremiah 22:11', 'Jeremiah', 22, 11, '&nbsp;نو بيا مالِک خُدائ د يوسياه د زوئ سلوم په حقله فرمائى، څوک چې د پلار نه پس د يهوداه بادشاه جوړ شوے وو، ”هغه د دې ځائ نه لاړو او هغه به هيڅکله نۀ راواپس کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18353, 'Jeremiah 22:12', 'Jeremiah', 22, 12, '&nbsp;هغه به په هغه ځائ کښې مړ شى چرته چې هغوئ قېدى بوتلے دے او هغه به دا مُلک بيا دوباره هيڅکله ونۀ ګورى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18354, 'Jeremiah 22:13', 'Jeremiah', 22, 13, '&nbsp;”افسوس دے په يهويقيم څوک چې په ناجائزه او په زور سره په مزدورانو باندې خپل محل جوړوى، څوک چې په بې‌اِنصافۍ سره د هغې دېوالونه خېژوى، ځکه چې هغه په خپلو خلقو بغېر پېسو کار کوى. هغه هغوئ ته مزدورى هم نۀ ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18355, 'Jeremiah 22:14', 'Jeremiah', 22, 14, '&nbsp;هغه وائى چې، زۀ به د خپل ځان دپاره يو لوئ محل جوړ کړم چې په کښې بره لوئې کوټې او ډيرې اوچتې کړکۍ وى او د لرګى کار به يې په خوشبودار دِيار سره وکړم او تک سور رنګ به ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18356, 'Jeremiah 22:15', 'Jeremiah', 22, 15, '&nbsp;خو د دِيار نه د ښائسته محلونو جوړول څوک لوئ بادشاه نۀ جوړوى. بې‌شکه ستا پلار، يوسياه، سره خو د خوړلو او څښلو دپاره هر څۀ ډېر تېر وُو، خو سره د دې هغه په خپله هره معامله کښې صادق او اِنصاف کوونکے وو، نو ځکه مالِک خُدائ ورله برکت ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18357, 'Jeremiah 22:16', 'Jeremiah', 22, 16, '&nbsp;هغۀ به غريبانانو او محتاجو له امداد او اِنصاف ورکولو، د دې په بدل کښې ورته برکت مِلاو شو. نو د دې ښکاره مطلب دا دے، څوک چې داسې کوى نو هغه ما پېژنى، مالِک خُدائ داسې فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18358, 'Jeremiah 22:17', 'Jeremiah', 22, 17, '&nbsp;خو ستاسو سترګې او زړۀ صرف د ناروا پېسو ګټلو طرف ته متوجه شوى دى، د بې‌ګناه خلقو وينه توئيوئ او دلته په هغوئ باندې ظلم او زياتے کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18359, 'Jeremiah 22:18', 'Jeremiah', 22, 18, '&nbsp;نو مالِک خُدائ د يهوداه بادشاه، د يوسياه د زوئ يهويقيم په حقله فرمائى، ”خلق به ستا په مرګ ماتم نۀ کوى تر دې چې ستا په کور کښې به هيڅ څوک هم د غم او افسوس اظهار نۀ کوى او نۀ به څوک ووائى چې افسوس دے، اے مالِکه. افسوس ستا شان شوکت لاړو ختم شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18360, 'Jeremiah 22:19', 'Jeremiah', 22, 19, '&nbsp;هغه به داسې ښخ کړے شى لکه څنګه چې يو خر ښخولے شى، هغه به راښکلے شى او د يروشلم د دروازو نه به بهر وغورزولے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18361, 'Jeremiah 22:20', 'Jeremiah', 22, 20, '&nbsp;”اے د يروشلم خلقو، بره لبنان ته لاړ شئ او چغې ووهئ، ستاسو د ژړا آواز دې په بسن کښې واورېدے شى، او د عباريم نه ژړا وکړئ، ځکه چې ستاسو ټول ملګرى تباه شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18362, 'Jeremiah 22:21', 'Jeremiah', 22, 21, '&nbsp;ما په هغه وخت کښې تاسو ته خبردارے درکړو کله چې تاسو ښۀ په آرام وئ، خو تاسو ووئيل، مونږ مۀ تنګوه. د ځوانۍ نه ستاسو هم دا عادت وو، تاسو زما تابعدارى نۀ ده کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18363, 'Jeremiah 22:22', 'Jeremiah', 22, 22, '&nbsp;زما د غضب طوفان به ستاسو ټول شپونکى جارُو کړى، او ستاسو ټول دوستان به جلاوطن کړى او هلته به غلامان شى او تاسو به د خپلو بدو عملونو په وجه سپک او شرمنده شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18364, 'Jeremiah 22:23', 'Jeremiah', 22, 23, '&nbsp;تاسو څوک چې په لبنان کښې اوسېږئ، او ځان ته مو د دِيار نه جاله جوړه کړې ده، تاسو به د دردونو په وجه داسې زبيرګى کوئ لکه چې يوه ښځه يې د ماشوم د پېدا کېدو په وخت کښې کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18365, 'Jeremiah 22:24', 'Jeremiah', 22, 24, '&nbsp;مالِک خُدائ يهوياکين ته چې، د يهويقيم زوئ او د يهوداه بادشاه دے وفرمائيل، ”زما دې په خپل ذات قسم وى، کۀ چرې تۀ زما د ښى لاس ګوتمه هم ولې نۀ وے نو تۀ به بيا هم ما ايستلې او اخوا غورزولې وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18366, 'Jeremiah 22:25', 'Jeremiah', 22, 25, '&nbsp;زۀ به تاسو هغه چا ته حواله کړم څوک چې ستا ژوند ختمول غواړى او د چا نه چې تۀ يرېږې. زۀ به تا د بابل بادشاه نبوکدنضر او د هغۀ خلقو ته حواله کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18367, 'Jeremiah 22:26', 'Jeremiah', 22, 26, '&nbsp;زۀ به تا او ستا مور د دې مُلک نه جلاوطن کړم، او تاسو به په پردى مُلک کښې مړۀ شئ، په هغه مُلک کښې چرته چې تاسو پېدا شوى نۀ يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18368, 'Jeremiah 22:27', 'Jeremiah', 22, 27, '&nbsp;تاسو به دې مُلک ته بيا هيڅکله هم واپس رانۀ شئ کوم چې تاسو غوښتل چې هغه بيا ووينئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18369, 'Jeremiah 22:28', 'Jeremiah', 22, 28, '&nbsp;خلقو ووئيل چې، ”ولې دا سړے يهوياکين بادشاه د هغه مات منګى په شان دے څۀ، کوم چې غورزولے شوے وى او د هيچا په کار نۀ وى؟ هغه او د هغۀ بچى ولې په يو داسې مُلک کښې جلاوطن کړے شوى دى چې هغوئ ته هيڅ پته هم نۀ وى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18370, 'Jeremiah 22:29', 'Jeremiah', 22, 29, '&nbsp;اے زما وطنه، زما وطنه، زما وطنه. د مالِک خُدائ دې پېغام ته غوږ ونيسه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18371, 'Jeremiah 22:30', 'Jeremiah', 22, 30, '&nbsp;مالِک خُدائ دا فرمائى چې، ”دا کس په بې‌اولادو کښې حساب کړه، دا کس به په خپل ټول ژوند کښې نۀ خوشحاله او نۀ آباد شى. د هغۀ د اولاد نه به څوک هم آباد نۀ شى، او يو به هم نۀ د داؤد په تخت کښېنى، او نۀ به په يهوداه کښې حکومت وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18372, 'Jeremiah 23:1', 'Jeremiah', 23, 1, '&nbsp;مالِک خُدائ فرمائى چې، ”افسوس دے د قوم په شپونکو باندې څوک چې زما د څرن د ځائ ګډې تباه کوى او خوروى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18373, 'Jeremiah 23:2', 'Jeremiah', 23, 2, '&nbsp;نو ځکه مالِک خُدائ، د بنى اِسرائيلو خُدائ پاک، دې شپونکو ته فرمائى چې، ”تاسو زما رمې خورې ورې کړې او د خپل ځان نه مو لرې شړلې دى او د هغوئ مو ښۀ خيال نۀ دے ساتلے، زۀ به تاسو له د دې بد کار سزا درکړم، مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18374, 'Jeremiah 23:3', 'Jeremiah', 23, 3, '&nbsp;زۀ به په خپله د خپلې رمې باقى پاتې شوى خلق د هغه ټولو مُلکونو نه راغونډ کړم کومو ته چې ما شړلى وُو او خپل وطن ته به يې واپس راولم. چرته چې به هغوئ مېوه ونيسى او د هغوئ شمېر به ډېر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18375, 'Jeremiah 23:4', 'Jeremiah', 23, 4, '&nbsp;زۀ به په هغوئ شپونکى مقرر کړم چې د هغوئ خيال وساتى، او هغوئ به نور د چا نه نۀ يريږى او نۀ به پرېشانه شى. او نۀ به يو ورک شى. ما مالِک خُدائ دا وفرمائيل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18376, 'Jeremiah 23:5', 'Jeremiah', 23, 5, '&nbsp;مالِک خُدائ فرمائى چې، ”هغه ورځې راتلونکې دى چې، زۀ به د داؤد په نسل کښې يوه صادقه څانګه راپورته کړم او بادشاه به يې کړم، او هغه به په هوښيارتيا سره حکومت کوى. او هغه به په مُلک کښې صداقت او اِنصاف قائم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18377, 'Jeremiah 23:6', 'Jeremiah', 23, 6, '&nbsp;په هغه ورځو کښې به يهوداه بچ کړے شى او اِسرائيل به د سلامتۍ سره ژوند کوى. او دا هغه نوم دے چې په کوم سره به هغه ياديږى، مالِک خُدائ زمونږ خلاصونکے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18378, 'Jeremiah 23:7', 'Jeremiah', 23, 7, '&nbsp;مالِک خُدائ فرمائى چې، ”نو هغه ورځې راتلونکې دى چې خلق به نور داسې قسم نۀ خورى چې په هغه ژوندى خُدائ مو دې قسم وى چا چې بنى اِسرائيل د مِصر نه رابهر کړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18379, 'Jeremiah 23:8', 'Jeremiah', 23, 8, '&nbsp;خو هغوئ به داسې وائى چې، قسم دے په هغه ژوندى مالِک خُدائ باندې چا چې د بنى اِسرائيل نسل د شمال او د نورو مُلکونو نه واپس راغونډ کړو کله چې هغۀ هغوئ تس نس کړى وُو. نو بيا به هغوئ په خپل مُلک کښې اوسيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18380, 'Jeremiah 23:9', 'Jeremiah', 23, 9, '&nbsp;زما زړۀ د دروغژنو نبيانو په وجه مات شوے دے، او ټول هډُوکى مې په لړزان دى. زۀ لکه د هغه نشائى په شان شوے يم څوک چې په شرابو زيات نشه شوے وى، نو دغه شان زۀ د مالِک خُدائ او د مقدس کلام په وجه نشه يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18381, 'Jeremiah 23:10', 'Jeremiah', 23, 10, '&nbsp;دا مُلک د زناکارانو نه ډک دے، نو په دې وجه مالِک خُدائ ورباندې لعنت نازل کړے دے نو زمکه اوچه شوې ده او په للمه کښې شينکے اوچ شوے دے. نبيان په بدو لارو روان شوى دى او خپل طاقت په غلطه طريقه استعمالوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18382, 'Jeremiah 23:11', 'Jeremiah', 23, 11, '&nbsp;مالِک خُدائ فرمائى چې، ”نبيان او اِمامان دواړه بې‌خُدايه کارونه کوى، تر دې چې ما په خپل کور کښې هم د دوئ بدعملۍ پېدا کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18383, 'Jeremiah 23:12', 'Jeremiah', 23, 12, '&nbsp;نو په دې وجه چې هغوئ چرته هم ځى د هغوئ پښې به ښوئيږى، او د تيارو خوا ته به بوتلے شى او هلته به هغوئ راوغورزيږى. زۀ به په هغوئ باندې د هغوئ د سزا په مقرر شوى وخت کښې افت نازل کړم.“ مالِک خُدائ داسې فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18384, 'Jeremiah 23:13', 'Jeremiah', 23, 13, '&nbsp;”ما د سامريه د نبيانو دا خراب کارونه وليدل چې کوم هغوئ د بعل په نوم پېشګوئې خلقو ته کوله او زما قوم بنى اِسرائيل يې بې‌لارې کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18385, 'Jeremiah 23:14', 'Jeremiah', 23, 14, '&nbsp;خو ما د يروشلم په پېغمبرانو کښې د دې نه زيات خراب کار وليدلو، هغوئ زنا کوى او بې‌ايمانى کوى، او د بدعملو خلقو حوصله افزائى کوى، نو بيا يو هم د خپلو بد عملونو نه نۀ منع کيږى. هغوئ ټول زما دپاره د سدوم د خلقو په شان خراب دى، او د يروشلم خلق ما ته د عموره د خلقو په شان بد دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18386, 'Jeremiah 23:15', 'Jeremiah', 23, 15, '&nbsp;نو ځکه مالِک خُدائ ربُ الافواج د يروشلم د نبيانو په حقله داسې فرمائى، ”زۀ به هغوئ ته د خوړلو دپاره تريخ خوراک او د څښلو دپاره به ورله د زهرو اوبۀ ورکړم، ځکه چې د يروشلم د نبيانو په وجه، په ټول مُلک کښې بې‌دينى خوره شوې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18387, 'Jeremiah 23:16', 'Jeremiah', 23, 16, '&nbsp;مالِک خُدائ ربُ الافواج خپلو خلقو ته فرمائى چې، ”دا نبيان چې تاسو ته کومه پېشګوئې کوى د هغوئ خبرو ته غوږ مۀ نيسئ، هغوئ تاسو د دروغو په اُميدونو سره ډکوى. هغوئ تاسو ته د مالِک خُدائ پېغام نۀ درکوى خو صرف د خپل سوچ او زړۀ نه تاسو ته رويا پېش کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18388, 'Jeremiah 23:17', 'Jeremiah', 23, 17, '&nbsp;هغوئ هغه خلقو ته مسلسل خبرې کوى څوک چې ما سپک ګڼى، چې مالِک خُدائ فرمائى چې تاسو به په خير خيريت يئ. او هغوئ ټولو ته څوک چې د خپل سرکشه زړۀ تابعدارى کوى هغوئ وائى تاسو ته به هيڅ قسمه نقصان ونۀ رسيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18389, 'Jeremiah 23:18', 'Jeremiah', 23, 18, '&nbsp;خو په هغوئ کښې کوم يو د مالِک خُدائ په حضور کښې ولاړ وو چې هغه څۀ يې ليدلى يا اورېدلى وى کوم چې هغۀ فرمائيلى دى؟ يو هم نه. چا هغۀ ته غوږ نيولے او چا د هغۀ آواز اورېدلے دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18390, 'Jeremiah 23:19', 'Jeremiah', 23, 19, '&nbsp;ګورئ د مالِک خُدائ غضب لکه د طوفان په شان راروان دے، او د هغۀ غضب به د ډېر تېز طوفان په شان د بدعملو په سرونو باندې راتاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18391, 'Jeremiah 23:20', 'Jeremiah', 23, 20, '&nbsp;او د مالِک خُدائ دا غضب به تر هغې پورې سوړ نۀ شى ترڅو پورې چې د هغۀ د زړۀ مقصد پوره شوے نۀ وى. په راتلونکو ورځو کښې به تاسو په دې ټولو باندې پوره پوهه شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18392, 'Jeremiah 23:21', 'Jeremiah', 23, 21, '&nbsp;”ما دا نبيان نۀ دى لېږلى، خو هغوئ د خپل ځان نه د پېغام ورکولو دپاره په منډه شوى دى، ما د هغوئ سره خبرې نۀ دى کړې، خو هغوئ پېشګويانې وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18393, 'Jeremiah 23:22', 'Jeremiah', 23, 22, '&nbsp;کۀ چرې هغوئ زما په حضور کښې ما سره ولاړ وے، نو هغوئ به بيا زما کلام خلقو ته اورولو او هغوئ به يې د خپلو شرارتونو او بدعملونو نه را اړول.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18394, 'Jeremiah 23:23', 'Jeremiah', 23, 23, '&nbsp;مالِک خُدائ فرمائى چې، ”زۀ هغه خُدائ پاک يم چې هر چرته حاضر ناظر يم نه چې په يو ځائ کښې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18395, 'Jeremiah 23:24', 'Jeremiah', 23, 24, '&nbsp;ولې داسې څوک شته چې زما نه خپل ځان چرته پټ کړى او زۀ هغه ونۀ وينم؟“ مالِک خُدائ فرمائى. ”ولې زۀ په هر ځائ زمکه او آسمان کښې نۀ يم څۀ؟“ مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18396, 'Jeremiah 23:25', 'Jeremiah', 23, 25, '&nbsp;”ما هغه هر څۀ واورېدل څۀ چې دې پېغمبرانو خلقو ته وفرمائيل څوک چې زما په نوم دروغ وائى او خلقو ته وائى چې، ما خوب وليدو. په خوب کښې په ما الهام وشو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18397, 'Jeremiah 23:26', 'Jeremiah', 23, 26, '&nbsp;دا خبرې به ترڅو پورې د دې دروغژنو پېغمبرانو په زړونو کښې راځى، څوک چې د خپلو سوچونو پېغامونه خلقو ته بيانوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18398, 'Jeremiah 23:27', 'Jeremiah', 23, 27, '&nbsp;د هغوئ خيال دا دے چې کوم خوبونه چې دوئ په خپلو کښې يو بل ته بيانوى نو د دې په وجه به زما خلق زما نوم هېر کړى، لکه څنګه چې پخوا د دوئ پلار نيکۀ زما نوم هېر کړے وو او د بعل بُت عبادت يې وکړو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18399, 'Jeremiah 23:28', 'Jeremiah', 23, 28, '&nbsp;مالِک خُدائ فرمائى چې، ”کوم پېغمبر چې خوب ليدلے دے هغه دې بې‌شکه خپل خوب بيان کړى، خو چې په چا زما کلام نازل شوے دے هغه دې په وفادارۍ سره کلام خلقو ته واوروى. تش بوس د غنمو برابر دى څۀ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18400, 'Jeremiah 23:29', 'Jeremiah', 23, 29, '&nbsp;مالِک خُدائ فرمائى چې، ”آيا زما پېغام د اور په شان نۀ دے څۀ، او زما پېغام د څټک په شان نۀ دے څۀ چې ګټ ټوټه ټوټه کوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');